from itertools import combinations
import networkx as nx

known_edges = [(5,9), (2,7), (1,4), (0,8), (1,5), (1,9), (6,8), (5,6), (4,8), (7,8), (3,8)]

def check_constraints(edges):
    G = nx.Graph()
    G.add_nodes_from(range(11))
    G.add_edges_from(edges)

    # Check min degree >= 4
    for v in range(11):
        if G.degree(v) < 4:
            return False, f"Vertex {v} has degree {G.degree(v)}"

    # Check vertex connectivity >= 4
    try:
        conn = nx.node_connectivity(G)
        if conn < 4:
            return False, f"Connectivity is {conn}"
    except:
        return False, "Connectivity check failed"

    # Check max independent set <= 4
    for subset in combinations(range(11), 5):
        is_independent = True
        for i in range(5):
            for j in range(i+1, 5):
                if G.has_edge(subset[i], subset[j]):
                    is_independent = False
                    break
            if not is_independent:
                break
        if is_independent:
            return False, f"Independent set of size 5: {subset}"

    return True, "OK"

# Let's try a greedy approach: add edges to vertices with low degree
# and try to break independent sets

# All possible edges not in known_edges
