# Let's try a random search approach
import random

def try_random_addition(known_edges, remaining, num_trials=10000):
    best = None
    best_score = float('inf')

    for trial in range(num_trials):
        edges = list(known_edges)
        # Randomly add some edges
        random.shuffle(remaining)
        for e in remaining:
            if random.random() < 0.4:  # 40% chance to add each edge
                edges.append(e)

        G = nx.Graph()
        G.add_nodes_from(range(11))
        G.add_edges_from(edges)

        # Quick check: min degree
        min_deg = min(G.degree(v) for v in range(11))
        if min_deg < 4:
            continue

        # Check connectivity
        try:
            conn = nx.node_connectivity(G)
        except:
            continue
        if conn < 4:
            continue

        # Check independent set
        has_bad_is = False
        for subset in combinations(range(11), 5):
            is_independent = True
            for i in range(5):
                for j in range(i+1, 5):
                    if G.has_edge(subset[i], subset[j]):
                        is_independent = False
                        break
                if not is_independent:
                    break
            if is_independent:
                has_bad_is = True
                break

        if not has_bad_is:
            return edges, len(edges)

        # Track best (closest to satisfying)
        score = len(edges)
        if score < best_score:
            best_score = score
            best = edges

    return best, best_score

result, score = try_random_addition(known_edges, remaining, 50000)
